export const state = () => ({
  chats: {},
  activeChatId: null,
  chatEvents: {},
  chatLoadingStatus: {}, // { [chatId]: ENTITY_STATUS }
  needsReload: {}, // { [chatId]: true } chat only carries a summary (last message) and must be fully reloaded before display
  searchResults: null,
